'use strict';
const D=window.ELECTION_DATA, $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmt=(n,d=0)=>n===null||n===undefined||!Number.isFinite(+n)?'—':Number(n).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const pct=(a,b)=>b>0&&a!==null?a/b*100:null, pstr=n=>n===null?'Indisponível':fmt(n,2)+'%', esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
const names={overview:'Visão geral',state:'Mapa de Santa Catarina',neighborhoods:'Florianópolis por bairro',compare:'Comparações',scenarios:'Cenários',sources:'Fontes e metodologia'};
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',state:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',neighborhoods:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',compare:'M4 4v16 M10 9v11 M16 3v17 M22 12v8',scenarios:'M3 19 8 13 13 16 21 5 M16 5h5v5',sources:'M5 3h11l4 4v14H5z M15 3v5h5 M8 12h9 M8 16h9'};
const icon=id=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="${icons[id]||icons.overview}"/></svg>`;
const officeColor=e=>e.officeCode===13?'#b07030':e.officeCode===7?'#00858c':'#7960af';
const S={route:'overview',year:2026,office:'all',territory:'SC',search:'',metric:'votes',sort:'votes',selected:null,compareA:2018,compareB:2026,compareLevel:'municipalities',scenarios:null};
const election=(y=S.year)=>D.elections.find(e=>e.year===+y), sum=(rows,k)=>rows.length&&rows.some(r=>r[k]===null)?null:rows.reduce((a,r)=>a+(r[k]||0),0);
const totalOf=rows=>Object.fromEntries(['votes','validVotes','electorate','turnout','abstentions','blankVotes','nullVotes','partyVotes','subJudiceVotes','otherInvalidVotes'].map(k=>[k,sum(rows,k)]));
const greater=new Set(D.greaterFlorianopolis.map(norm));
function territoryRows(e,territory=S.territory){if(e.officeCode===13)return ['SC','GF','81051'].includes(territory)?e.municipalities:[];return e.municipalities.filter(r=>territory==='SC'||territory==='GF'&&greater.has(norm(r.name))||r.id===territory);}
// O recorte obrigatório da disputa não altera o filtro territorial escolhido.
const electionTerritory=e=>e.officeCode===13?'81051':S.territory;
function rowsFor(e=election(),level=S.route==='neighborhoods'?'neighborhoods':'municipalities',query=S.search){const base=level==='neighborhoods'?e.neighborhoods:territoryRows(e,electionTerritory(e));return base.filter(r=>norm(r.name).includes(norm(query)));}
const sorted=rows=>[...rows].sort((a,b)=>S.sort==='name'?a.name.localeCompare(b.name,'pt-BR'):(S.sort==='share'?(pct(b.votes,b.validVotes)??-1)-(pct(a.votes,a.validVotes)??-1):b.votes-a.votes));
function metricValue(r){return S.metric==='share'?pct(r.votes,r.validVotes):r.votes;}
const colors=['#ffffff','#d7eeed','#a3d5d2','#63b4b0','#228d90','#075b68'];
function thresholds(){return S.metric==='share'?[0,.25,.5,1,2,4]:[0,50,200,500,2000,5000];}
function fill(v){if(v===null||v===undefined)return 'url(#missing)';if(v===0)return colors[0];let t=thresholds();let i=1;for(let k=1;k<t.length;k++)if(v>=t[k])i=Math.min(k+1,5);return colors[i];}
function legend(){let t=thresholds(),lab=S.metric==='share'?v=>fmt(v,2)+'%':v=>fmt(v);return `<div class="legend"><span><i style="background:white"></i>Zero</span>${colors.slice(1).map((c,i)=>`<span><i style="background:${c}"></i>${i===0?'> 0':lab(t[i])} ${i===4?'ou mais':'– < '+lab(t[i+1])}</span>`).join('')}<span><i style="background:repeating-linear-gradient(45deg,#d9e0e7 0 2px,#f1f4f7 2px 5px)"></i>Sem dado</span><span><i style="background:#e7edf2"></i>Fora do filtro / não aplicável</span></div>`;}
function segmented(){return `<div class="segmented" aria-label="Indicador no mapa"><button data-metric="votes" class="${S.metric==='votes'?'active':''}">Votos</button><button data-metric="share" class="${S.metric==='share'?'active':''}">% válidos</button></div>`;}
const allCoords=geometry=>geometry.type==='Polygon'?geometry.coordinates:geometry.coordinates.flat();
function mapSvg(e,level='municipalities',rows=rowsFor(e,level),id='main-map'){
 const cityFeature=D.geography.features.find(f=>f.properties.codarea==='4205407');const features=level==='neighborhoods'?[cityFeature]:D.geography.features;
 const pts=features.flatMap(f=>allCoords(f.geometry).flat());const xs=pts.map(p=>p[0]*.886),ys=pts.map(p=>-p[1]);const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys),w=800,h=490,scale=Math.min((w-76)/(x1-x0),(h-60)/(y1-y0));
 const point=([x,y])=>[(x*.886-(x0+x1)/2)*scale+w/2,(-y-(y0+y1)/2)*scale+h/2];
 const path=g=>allCoords(g).map(r=>'M'+r.map(p=>point(p).map(v=>v.toFixed(2)).join(',')).join('L')+'Z').join('');
 const byibge=new Map(rows.map(r=>[r.ibge,r]));const visible=new Set(rows.map(r=>r.name));const locales=e.locations.filter(l=>visible.has(l.neighborhood)&&l.latitude!==null&&l.longitude!==null);
 return `<svg id="${id}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${level==='neighborhoods'?'Locais de votação em Florianópolis':'Municípios de Santa Catarina'} em ${e.year}"><defs><pattern id="missing" patternUnits="userSpaceOnUse" width="7" height="7"><rect width="7" height="7" fill="#eef2f6"/><path d="M-1 1 1-1 M0 7 7 0 M6 8 8 6" stroke="#d1dae3" stroke-width="1"/></pattern></defs><rect width="800" height="490" fill="#f8fbfc"/><text x="26" y="33" fill="#577183" font-size="13" font-family="sans-serif">${e.year} · ${esc(e.office)} · ${S.metric==='votes'?'Votos absolutos':'% dos votos válidos locais'}</text>${features.map(f=>{let r=byibge.get(f.properties.codarea),v=r?metricValue(r):null;return `<path d="${path(f.geometry)}" fill="${level==='neighborhoods'?'#e9f0f2':r?fill(v):'#e7edf2'}" stroke="${level==='neighborhoods'?'#a9bcc8':'#fff'}" stroke-width="${level==='neighborhoods'?1.5:.8}" ${level==='municipalities'&&r?`class="territory ${S.selected===r.id?'selected':''}" tabindex="0" role="button" aria-label="${esc(r.name)}: ${fmt(r.votes)} votos" data-map-id="${r.id}" data-map-year="${e.year}" data-map-level="${level}"`:''}/>`}).join('')}${level==='neighborhoods'?locales.map(l=>{const [x,y]=point([l.longitude,l.latitude]);return `<circle class="location" cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="${S.metric==='votes'?Math.max(3,Math.min(11,2+Math.sqrt(l.votes)*.42)):5}" fill="${fill(metricValue(l))}" fill-opacity=".88" stroke="#41747d" stroke-width=".8" tabindex="0" role="button" aria-label="${esc(l.name)}: ${fmt(l.votes)} votos" data-map-id="${esc(l.id)}" data-map-year="${e.year}" data-map-level="locations"/>`;}).join(''):''}<text x="770" y="467" text-anchor="end" fill="#748797" font-size="11" font-family="sans-serif">Limites municipais · IBGE</text><text x="770" y="57" text-anchor="end" fill="#577183" font-size="13" font-family="sans-serif">N ↑</text></svg>`;
}
function filters(){const e=S.route==='compare'?election(2026):election(),neigh=S.route==='neighborhoods'||(S.route==='compare'&&S.compareLevel==='neighborhoods'),forcedCity=S.route==='compare'&&(election(S.compareA).officeCode===13||election(S.compareB).officeCode===13);return `<div class="filters"><div class="field" ${S.route==='compare'?'hidden':''}><label for="year">Eleição</label><select id="year">${D.elections.filter(a=>S.office==='all'||a.officeCode===+S.office).map(a=>`<option value="${a.year}" ${a.year===S.year?'selected':''}>${a.year} · ${a.party}</option>`).join('')}</select></div><div class="field" ${S.route==='compare'?'hidden':''}><label for="office">Cargo</label><select id="office"><option value="all">Todos os cargos</option>${[[13,'Vereador'],[7,'Deputado estadual'],[6,'Deputado federal']].map(([v,n])=>`<option value="${v}" ${String(v)===S.office?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="territory">Território</label><select id="territory" ${neigh||forcedCity||e.officeCode===13?'disabled':''}>${neigh||forcedCity||e.officeCode===13?'<option>Florianópolis</option>':`<option value="SC">Santa Catarina</option><option value="GF" ${S.territory==='GF'?'selected':''}>Grande Florianópolis · 9 municípios</option>${[...e.municipalities].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).map(r=>`<option value="${r.id}" ${S.territory===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}`}</select></div><div class="field search" ${S.route==='scenarios'?'hidden':''}><label for="search">Buscar ${neigh?'bairro':'município'}</label><input id="search" type="search" placeholder="${neigh?'Ex.: Centro, Trindade…':'Ex.: Florianópolis, Joinville…'}" value="${esc(S.search)}"></div><button id="clear">Limpar</button></div>`;}
function kpis(e,rows,neigh=false){const t=totalOf(rows),full=neigh?e.municipalities.find(r=>r.id==='81051').votes:e.totals.votes;return `<div class="kpis"><div class="kpi"><span class="label">Votos no recorte</span><strong>${fmt(t.votes)}</strong><div class="detail">${rows.length} ${neigh?'bairros / localidades':'município(s)'} · ${e.year}</div></div><div class="kpi"><span class="label">Participação nos válidos</span><strong>${t.validVotes===null?'—':pstr(pct(t.votes,t.validVotes))}</strong><div class="detail">${t.validVotes===null?'Denominador não reconciliado':fmt(t.validVotes)+' votos nominais + legenda'}</div></div><div class="kpi"><span class="label">${neigh?'Da votação na capital':'Da votação total do candidato'}</span><strong>${pstr(pct(t.votes,full))}</strong><div class="detail">Base: ${fmt(full)} votos · ${neigh?'Florianópolis':e.territory}</div></div><div class="kpi"><span class="label">Resultado na circunscrição</span><strong class="word">${esc(e.result)}</strong><div class="detail">${e.party} · ${e.number} · ${esc(e.office)}</div></div></div>`;}
function ranking(e,rows,level){const ranks=sorted(rows).slice(0,8),max=Math.max(...rows.map(r=>S.sort==='share'?pct(r.votes,r.validVotes)||0:r.votes),1);return `<section class="panel"><div class="panel-head"><div><h2>Ranking ${level==='neighborhoods'?'por bairro':'municipal'}</h2><p>${S.sort==='share'?'Participação nos válidos locais':'Contribuição em votos absolutos'}</p></div><select id="ranking-sort" aria-label="Ordenar ranking" style="width:105px"><option value="votes">Votos</option><option value="share" ${S.sort==='share'?'selected':''}>% válidos</option></select></div><div class="rank-list">${ranks.length?ranks.map((r,i)=>`<button class="rank-row" data-select="${esc(r.id)}" data-level="${level}"><span class="rank-num">${String(i+1).padStart(2,'0')}</span><span><span class="rank-title">${esc(r.name)}</span><span class="rank-bar"><i style="width:${((S.sort==='share'?pct(r.votes,r.validVotes)||0:r.votes)/max*100).toFixed(2)}%"></i></span></span><span class="rank-value">${S.sort==='share'?pstr(pct(r.votes,r.validVotes)):fmt(r.votes)}<small>${S.sort==='share'?fmt(r.votes)+' votos':pstr(pct(r.votes,r.validVotes))+' local'}</small></span></button>`).join(''):'<p class="empty">Nenhum território encontrado.</p>'}</div><div class="table-footer">${Math.min(8,rows.length)} de ${rows.length} territórios no recorte</div></section>`;}
function selectedInfo(e,level){if(!S.selected)return '';let r=e[level].find(a=>a.id===S.selected)||e.locations.find(a=>a.id===S.selected);if(!r)return '';return `<div class="selected-info"><strong>${esc(r.name)}</strong><span>${fmt(r.votes)} votos · ${pstr(pct(r.votes,r.validVotes))} local</span>${r.id==='81051'?'<button id="drill">Ver bairros de Florianópolis</button>':''}${r.neighborhood?`<span>${esc(r.neighborhood)} · ${esc(r.address)}</span>`:''}<button id="deselect" aria-label="Fechar seleção">Fechar</button></div>`;}
function timeline(){return `<section class="panel"><div class="panel-head"><div><h2>Cinco eleições, três cargos</h2><p>Clique em uma candidatura para explorar os resultados.</p></div><button data-export="timeline-chart">Exportar gráfico</button></div><div class="timeline">${D.elections.map(e=>`<button data-year="${e.year}" class="${e.year===S.year?'active':''}"><span class="year">${e.year}</span><span class="office"><i class="office-dot" style="background:${officeColor(e)}"></i>${e.office}</span><strong>${fmt(e.totals.votes)}</strong><small>${e.party} · ${e.result}</small></button>`).join('')}</div><div class="panel-body" style="padding-top:0">${timelineSvg()}<p class="small">Gráfico: filtro territorial e busca ativos; cartões: totais das candidaturas. Cargos diferentes têm eleitorados e disputas diferentes. O total de votos, sozinho, não mede crescimento proporcional do apoio.</p></div></section>`;}
function timelineSvg(){const es=D.elections,values=es.map(e=>territoryRows(e).length?totalOf(territoryRows(e).filter(r=>norm(r.name).includes(norm(S.search)))).votes:null),max=Math.max(...values),h=190;return `<svg class="chart-svg" id="timeline-chart" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 210" role="img" aria-label="Votos por eleição, cargos diferenciados por cor"><rect width="1000" height="210" fill="white"/><text x="15" y="19" fill="#637487" font-size="12" font-family="sans-serif">${S.territory==='SC'?'Circunscrição de cada candidatura — recortes distintos':S.territory==='GF'?'Grande Florianópolis (vereador: somente Florianópolis)':'Município selecionado (vereador: somente Florianópolis)'}</text>${es.map((e,i)=>{const height=values[i]/max*125,x=60+i*195;return `<rect x="${x}" y="${h-height-22}" width="95" height="${height}" fill="${officeColor(e)}" rx="3"/><text x="${x+47}" y="${h-height-29}" text-anchor="middle" font-family="sans-serif" font-size="14" fill="#234056">${values[i]===null?'Não aplicável':fmt(values[i])}</text><text x="${x+47}" y="${h+2}" text-anchor="middle" font-family="sans-serif" font-size="13" fill="#637487">${e.year} · ${e.party}</text>`}).join('')}</svg>`;}
function insights(e,rows,level){if(!rows.length)return '';let ranked=[...rows].sort((a,b)=>b.votes-a.votes),t=sum(rows,'votes'),top5=sum(ranked.slice(0,5),'votes'),top10=sum(ranked.slice(0,10),'votes'),acc=0,n50=0,n80=0;for(let i=0;i<ranked.length;i++){acc+=ranked[i].votes;if(!n50&&acc>=t*.5)n50=i+1;if(!n80&&acc>=t*.8)n80=i+1;}let best=[...rows].filter(r=>r.validVotes>0).sort((a,b)=>b.votes/b.validVotes-a.votes/a.validVotes)[0],territory=level==='neighborhoods'?'bairros de Florianópolis':'municípios no recorte';const src=`${e.year} · ${territory} · TSE · consulta 07/10/2026`;
 return `<div class="insights"><article class="insight"><h3>Concentração territorial</h3><span class="num">${pstr(pct(top5,t))}</span><p>Os ${Math.min(5,rows.length)} primeiros somam ${fmt(top5)} votos. Os ${Math.min(10,rows.length)} primeiros reúnem ${pstr(pct(top10,t))}. ${n50} territórios chegam a 50% da votação; ${n80}, a 80%.</p><small>${src}</small></article><article class="insight"><h3>Volume e participação</h3><span class="num">${fmt(ranked[0].votes)} votos</span><p>${esc(ranked[0].name)} lidera em volume.${best?` Em participação local, ${esc(best.name)} lidera com ${pstr(pct(best.votes,best.validVotes))} (${fmt(best.votes)} de ${fmt(best.validVotes)} válidos).`:' O percentual local não está disponível: o denominador por seção não fecha com a totalização.'}</p><small>${src}</small></article><article class="insight"><h3>Alcance no recorte</h3><span class="num">${fmt(rows.filter(r=>r.votes>0).length)} de ${fmt(rows.length)}</span><p>Territórios com ao menos um voto. ${fmt(rows.filter(r=>r.votes===0).length)} têm votação zero registrada.${level==='neighborhoods'?` Cobertura de classificação: ${pstr(e.audit.classifiedVoteCoverage)} dos votos da capital.`:` O recorte representa ${pstr(pct(t,e.totals.votes))} dos ${fmt(e.totals.votes)} votos da candidatura.`}</p><small>${src}</small></article></div>`;
}
function context(e,rows){const t=totalOf(rows);return `<section class="panel section-gap"><div class="panel-head"><div><h2>Contexto eleitoral do recorte</h2><p>Mesmo ano, cargo e territórios selecionados · TSE</p></div></div><div class="panel-body"><div class="context-grid">${[['Eleitorado',t.electorate],['Comparecimento',t.turnout],['Abstenções',t.abstentions],['Brancos para o cargo',t.blankVotes],['Nulos para o cargo',t.nullVotes]].map(([l,v])=>`<div><span>${l}</span><b>${fmt(v)}</b></div>`).join('')}</div><p class="small section-gap">Comparecimento: ${pstr(pct(t.turnout,t.electorate))}. Válidos: ${pstr(pct(t.validVotes,t.turnout))} do comparecimento. Anulados: ${fmt(t.otherInvalidVotes)}; anulados sub judice: ${fmt(t.subJudiceVotes)} (fora dos válidos). Esses números contextualizam a disputa; não demonstram a causa de uma variação de votos.</p></div></section>`;}
function regions(e){if(e.officeCode===13)return '';const rs=territoryRows(e).filter(r=>norm(r.name).includes(norm(S.search))),groups=[['Florianópolis',rs.filter(r=>r.id==='81051')],['Outros 8 da Grande Florianópolis',rs.filter(r=>r.id!=='81051'&&greater.has(norm(r.name)))],['Restante do estado',rs.filter(r=>!greater.has(norm(r.name)))]];return `<section class="panel section-gap"><div class="panel-head"><h2>Distribuição estadual · ${e.year}</h2></div><div class="panel-body">${groups.map(([name,r])=>`<div style="display:grid;grid-template-columns:1fr auto;gap:12px;margin-bottom:16px;font-size:14px"><span>${name}</span><strong>${fmt(sum(r,'votes'))} · ${pstr(pct(sum(r,'votes'),e.totals.votes))}</strong><span class="rank-bar" style="grid-column:1/-1;height:8px;margin:0"><i style="width:${pct(sum(r,'votes'),e.totals.votes)}%"></i></span></div>`).join('')}<p class="small">Percentuais sobre o total do candidato na eleição. Filtros e busca aplicados. Grande Florianópolis: ${D.greaterFlorianopolis.map(esc).join(', ')}. Recorte operacional de 9 municípios, mantido em todas as eleições estaduais.</p></div></section>`;}
function table(e,rows,level){return `<section class="panel section-gap"><div class="panel-head"><div><h2>${level==='neighborhoods'?'Votos por bairro do local de votação':'Resultados por município'}</h2><p>${rows.length} registros · clique no nome para detalhar</p></div><button id="export-csv">Exportar CSV</button></div><div class="table-wrap"><table><thead><tr><th><button data-sort="name">${level==='neighborhoods'?'Bairro / localidade':'Município'} ↕</button></th><th class="number"><button data-sort="votes">Votos ↕</button></th><th class="number"><button data-sort="share">% válidos locais ↕</button></th><th class="number">Válidos locais</th><th class="number">% do total do candidato</th>${level==='neighborhoods'?'<th class="number">Locais</th>':''}</tr></thead><tbody>${sorted(rows).map(r=>`<tr><td><button class="text-button" data-select="${esc(r.id)}" data-level="${level}">${esc(r.name)}</button></td><td class="number">${fmt(r.votes)}</td><td class="number">${pstr(pct(r.votes,r.validVotes))}</td><td class="number">${fmt(r.validVotes)}</td><td class="number">${pstr(pct(r.votes,e.totals.votes))}</td>${level==='neighborhoods'?`<td class="number">${r.locationIds.length}</td>`:''}</tr>`).join('')}</tbody></table>${!rows.length?'<p class="empty">Nenhum resultado para esta busca.</p>':''}</div><div class="table-footer">Válidos = nominais válidos + legenda válida (inclui conversões). “—” indica dado ausente; zero indica votação registrada igual a zero.</div></section>`;}
function neighborhoodDetail(e){let n=e.neighborhoods.find(r=>r.id===S.selected);if(!n)return '';const locs=e.locations.filter(l=>n.locationIds.includes(l.id));return `<section class="panel section-gap" id="location-detail"><div class="panel-head"><div><h2>${esc(n.name)} · locais de votação</h2><p>${fmt(n.votes)} votos · ${locs.length} locais · cadastro da eleição de ${e.year}</p></div><button id="export-locations">Exportar locais</button></div><div class="table-wrap"><table class="subtable"><thead><tr><th>Local / endereço</th><th>Zona · local</th><th class="number">Votos</th><th>Seções no resultado</th></tr></thead><tbody>${locs.map(l=>`<tr><td><strong>${esc(l.name)}</strong><br><span class="small">${esc(l.address||'Endereço não confirmado')}</span></td><td>${l.zone} · ${l.code}</td><td class="number">${fmt(l.votes)}</td><td>${l.sectionNumbers.join(', ')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function overview(){const e=election(),neigh=S.route==='neighborhoods',level=neigh?'neighborhoods':'municipalities',rows=rowsFor(e,level),a=e.audit;
 return `${filters()}${kpis(e,rows,neigh)}${neigh?`<div class="note teal"><strong>Votos por bairro do local de votação.</strong> O bairro identifica onde os votos foram registrados, não a residência dos eleitores. Classificados: ${pstr(a.classifiedVoteCoverage)} · não classificados: ${fmt(a.unclassifiedVotes)} votos. ${a.coordinatesLocations} de ${a.locations} locais têm coordenadas utilizáveis.</div>${!a.neighborhoodPercentagesAvailable?`<div class="note warning">Percentuais locais indisponíveis em ${e.year}: a reconstrução dos votos válidos por seção diverge em ${fmt(a.validVoteDifference)} votos da totalização municipal. Os votos de Bruno conferem integralmente. Veja a auditoria.</div>`:''}`:''}${e.officeCode===13&&!neigh?'<div class="note">Esta disputa abrange apenas Florianópolis. <button class="text-button" id="drill">Explorar votação por bairro</button></div>':''}<div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>${neigh?'Florianópolis · locais de votação':'Santa Catarina · distribuição dos votos'}</h2><p>${neigh?'Pontos do cadastro histórico, sem interpolação por área':'Selecione um município no mapa'}</p></div>${segmented()}</div><div class="map-wrap">${mapSvg(e,level,rows)}${!neigh?'<div class="map-label"><strong>SANTA CATARINA</strong>Primeiro turno</div>':''}</div>${legend()}${selectedInfo(e,level)}<div class="table-footer">${neigh?'Sem malha de bairros historicamente homologada: exibimos locais. Coordenadas são as publicadas no arquivo retrospectivo do TSE; sua precisão histórica não foi comprovada.':'Malha oficial IBGE consultada em 07/10/2026. Cores têm faixas fixas, iguais em todas as eleições.'} <button class="text-button" data-export="main-map">Salvar mapa em PNG</button></div></section>${ranking(e,rows,level)}</div>${neigh?neighborhoodDetail(e):S.route==='overview'?timeline():''}${insights(e,rows,level)}${table(e,rows,level)}${!neigh?regions(e)+context(e,rows):''}`;
}
function comparisonRows(){const a=election(S.compareA),b=election(S.compareB),level=S.compareLevel;const territory=a.officeCode===13||b.officeCode===13?'81051':S.territory;let aa=level==='neighborhoods'?a.neighborhoods:territoryRows(a,territory),bb=level==='neighborhoods'?b.neighborhoods:territoryRows(b,territory);if(a.officeCode===13||b.officeCode===13){aa=level==='municipalities'?aa.filter(r=>r.id==='81051'):aa;bb=level==='municipalities'?bb.filter(r=>r.id==='81051'):bb;}const ma=new Map(aa.map(r=>[r.id,r])),mb=new Map(bb.map(r=>[r.id,r]));return [...new Set([...ma.keys(),...mb.keys()])].map(id=>{const x=ma.get(id),y=mb.get(id);return {id,name:(x||y).name,a:x||null,b:y||null,delta:x&&y?y.votes-x.votes:null,growth:x&&y&&x.votes>0?(y.votes/x.votes-1)*100:null,pp:x&&y&&x.validVotes&&y.validVotes?pct(y.votes,y.validVotes)-pct(x.votes,x.validVotes):null};}).filter(r=>norm(r.name).includes(norm(S.search))).sort((a,b)=>(b.delta??-Infinity)-(a.delta??-Infinity));}
function compare(){const a=election(S.compareA),b=election(S.compareB),level=S.compareLevel,rs=comparisonRows(),aa=rs.filter(r=>r.a).map(r=>r.a),bb=rs.filter(r=>r.b).map(r=>r.b),ta=totalOf(aa),tb=totalOf(bb),delta=tb.votes-ta.votes,growth=ta.votes?(tb.votes/ta.votes-1)*100:null,pa=pct(ta.votes,ta.validVotes),pb=pct(tb.votes,tb.validVotes),same=a.officeCode===b.officeCode;const opt=y=>D.elections.map(e=>`<option value="${e.year}" ${e.year===y?'selected':''}>${e.year} · ${e.office} · ${e.party}</option>`).join('');return `${filters()}<div class="compare-controls"><div class="field"><label for="compare-a">Eleição de referência</label><select id="compare-a">${opt(a.year)}</select></div><div class="field"><label for="compare-b">Eleição de comparação</label><select id="compare-b">${opt(b.year)}</select></div><div class="field"><label for="compare-level">Unidade territorial</label><select id="compare-level"><option value="municipalities">Municípios</option><option value="neighborhoods" ${level==='neighborhoods'?'selected':''}>Bairros de Florianópolis</option></select></div></div><div class="note ${same?'teal':'warning'}">${same?`Mesmo cargo: ${esc(a.office)}. `:'Comparação entre cargos diferentes. '} ${a.officeCode===13||b.officeCode===13?'Recorte comum restrito a Florianópolis. ':''}${same?'Mudanças no eleitorado e na disputa precisam ser consideradas.':'Totais, concorrência e regras da disputa diferem. A variação não é prova de crescimento proporcional do apoio.'}${level==='neighborhoods'?' Os nomes de bairro foram alinhados apenas por grafia (acentos/caixa). Limites e composição de locais podem mudar; a tabela sinaliza alterações cadastrais.':''}</div><div class="kpis"><div class="kpi"><span class="label">${a.year} · recorte ${level==='neighborhoods'?'cadastral':'comum'}</span><strong>${fmt(ta.votes)}</strong><div class="detail">${pstr(pa)} dos válidos</div></div><div class="kpi"><span class="label">${b.year} · recorte ${level==='neighborhoods'?'cadastral':'comum'}</span><strong>${fmt(tb.votes)}</strong><div class="detail">${pstr(pb)} dos válidos</div></div><div class="kpi"><span class="label">Variação em votos</span><strong>${delta>0?'+':''}${fmt(delta)}</strong><div class="detail">${growth===null?'Base inicial zero ou ausente':(growth>0?'+':'')+fmt(growth,2)+'% em votos'}</div></div><div class="kpi"><span class="label">Variação de participação</span><strong>${pa!==null&&pb!==null?fmt(pb-pa,2)+' p.p.':'—'}</strong><div class="detail">Válidos do mesmo cargo e recorte</div></div></div><div class="toolbar" style="justify-content:space-between;margin-bottom:15px"><span class="small">Mesmas faixas de cores nos dois mapas · bases pequenas: menos de 100 votos na referência</span>${segmented()}</div><div class="two-col">${[[a,aa,'a'],[b,bb,'b']].map(([e,r,id])=>`<section class="panel"><div class="panel-head"><div><h2>${e.year} · ${e.office}</h2><p>${e.party} · ${fmt(sum(r,'votes'))} votos no recorte</p></div><button data-export="compare-${id}-map">PNG</button></div><div class="map-wrap">${mapSvg(e,level,r,'compare-'+id+'-map')}</div>${legend()}</section>`).join('')}</div><div class="insights"><article class="insight"><h3>Maior aumento absoluto</h3>${changeInsight(rs.find(r=>r.delta>0))}<small>${a.year}–${b.year} · recorte filtrado · TSE</small></article><article class="insight"><h3>Maior redução absoluta</h3>${changeInsight([...rs].reverse().find(r=>r.delta<0))}<small>${a.year}–${b.year} · recorte filtrado · TSE</small></article><article class="insight"><h3>Como ler a comparação</h3><p>${level==='neighborhoods'?'Mudanças de bairro, nome, endereço ou conjunto de locais impedem assumir continuidade territorial. Consulte a relação cadastral.':'Municípios são pareados pelo código TSE. O mapa usa a mesma malha IBGE atual para os dois anos; não reconstrói limites históricos.'} Estabilidade agregada não significa fidelidade dos mesmos eleitores; variações não demonstram transferência individual de votos.</p><small>Interpretação descritiva, sem inferência causal</small></article></div><section class="panel section-gap"><div class="panel-head"><div><h2>Variações territoriais</h2><p>Ordenadas pelo aumento absoluto de votos</p></div><button id="export-comparison">Exportar CSV</button></div><div class="table-wrap"><table><thead><tr><th>Território</th><th class="number">${a.year}</th><th class="number">${b.year}</th><th class="number">Δ votos</th><th class="number">Δ % votos</th><th class="number">Δ p.p.</th><th>Leitura</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${esc(r.name)}</td><td class="number">${fmt(r.a?.votes)}</td><td class="number">${fmt(r.b?.votes)}</td><td class="number">${r.delta>0?'+':''}${fmt(r.delta)}</td><td class="number">${r.growth===null?'—':fmt(r.growth,2)+'%'}</td><td class="number">${fmt(r.pp,2)}</td><td>${!r.a||!r.b?'Ausente em uma base':r.a.votes===0?'Base inicial zero':r.a.votes<100?'<span class="badge-warning">Base inicial pequena</span>':''}${level==='neighborhoods'?'<br>'+neighborhoodComparable(a,b,r):''}</td></tr>`).join('')}</tbody></table></div></section>${level==='municipalities'?regionComparison(a,b,aa,bb)+`<section class="panel section-gap"><div class="panel-head"><h2>Contexto no mesmo recorte</h2></div><div class="table-wrap"><table><thead><tr><th>Indicador</th><th class="number">${a.year}</th><th class="number">${b.year}</th><th class="number">Variação</th></tr></thead><tbody>${[['electorate','Eleitorado'],['turnout','Comparecimento'],['abstentions','Abstenções'],['blankVotes','Brancos para o cargo'],['nullVotes','Nulos para o cargo']].map(([k,l])=>`<tr><td>${l}</td><td class="number">${fmt(ta[k])}</td><td class="number">${fmt(tb[k])}</td><td class="number">${ta[k]!==null&&tb[k]!==null?fmt(tb[k]-ta[k]):'—'}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function neighborhoodComparable(a,b,r){if(!r.a||!r.b)return 'Sem par';const signature=(e,row)=>e.locations.filter(l=>row.locationIds.includes(l.id)).map(l=>[l.id,norm(l.name),norm(l.address||''),norm(l.neighborhood)].join('|')).sort().join(';');return signature(a,r.a)===signature(b,r.b)?'Mesmos locais cadastrados; limites não verificados':'Composição cadastral alterada';}
function regionComparison(a,b,aa,bb){const groups=[['Florianópolis',r=>r.id==='81051'],['Grande Florianópolis (9 municípios)',r=>greater.has(norm(r.name))],['Restante de Santa Catarina',r=>!greater.has(norm(r.name))]];return `<section class="panel section-gap"><div class="panel-head"><div><h2>Distribuição e alcance ao longo do tempo</h2><p>Filtros aplicados; contribuição sobre o total de cada candidatura.</p></div></div><div class="table-wrap"><table><thead><tr><th>Recorte</th><th class="number">${a.year} · votos</th><th class="number">% candidato</th><th class="number">${b.year} · votos</th><th class="number">% candidato</th></tr></thead><tbody>${groups.map(([label,fn])=>`<tr><td>${label}</td><td class="number">${fmt(sum(aa.filter(fn),'votes'))}</td><td class="number">${pstr(pct(sum(aa.filter(fn),'votes'),a.totals.votes))}</td><td class="number">${fmt(sum(bb.filter(fn),'votes'))}</td><td class="number">${pstr(pct(sum(bb.filter(fn),'votes'),b.totals.votes))}</td></tr>`).join('')}<tr><td>Municípios com votos</td><td class="number">${aa.filter(r=>r.votes>0).length}</td><td>de ${aa.length}</td><td class="number">${bb.filter(r=>r.votes>0).length}</td><td>de ${bb.length}</td></tr></tbody></table></div><div class="table-footer">A linha Grande Florianópolis inclui a capital; não somar as duas. Composição: ${D.greaterFlorianopolis.join(', ')}.</div></section>`;}
function changeInsight(r){if(!r)return '<span class="num">—</span><p>Não há variação deste tipo no recorte selecionado.</p>';return `<span class="num">${r.delta>0?'+':''}${fmt(r.delta)} votos</span><p>${esc(r.name)}: ${fmt(r.a.votes)} para ${fmt(r.b.votes)}. ${r.growth===null?'Crescimento percentual não definido sobre base zero.':fmt(r.growth,2)+'% de variação.'}${r.a.votes<100?' Base inicial pequena: grandes percentuais podem representar poucos votos.':''}</p>`;}
function initScenarios(force=false){if(S.scenarios&&!force)return;const e=election(),t=totalOf(territoryRows(e,electionTerritory(e))),share=pct(t.votes,t.validVotes)||0;S.scenarios=[.8,1,1.2].map(mult=>({electorate:t.electorate,turnout:+pct(t.turnout,t.electorate).toFixed(6),valid:+pct(t.validVotes,t.turnout).toFixed(6),share:+(share*mult).toFixed(6)}));}
function scenarioValue(r){return Math.round(r.electorate*(r.turnout/100)*(r.valid/100)*(r.share/100));}
function scenarios(){initScenarios();const e=election(),territory=e.officeCode===13?'Florianópolis':S.territory==='SC'?e.territory:S.territory==='GF'?'Grande Florianópolis':e.municipalities.find(r=>r.id===S.territory)?.name||e.territory;return `${filters()}<div class="note warning"><strong>Simulação condicional, não previsão.</strong> Os três cenários são hipóteses editáveis. Não têm probabilidades nem intervalos de confiança e não estimam eleição ou cadeiras.</div><div class="scenario-formula"><span class="small" style="color:#b1c9d8">Fórmula aplicada a cada cenário</span><code>Votos = eleitorado × comparecimento × proporção de válidos × participação do candidato</code></div><div class="panel-head" style="padding:0 0 20px;border:0"><div><h2>Referência observada: ${e.year} · ${esc(e.office)}</h2><p>${esc(territory)} · ${fmt(totalOf(territoryRows(e,electionTerritory(e))).votes)} votos observados. Válidos incluem legenda. Busca por nome não altera a circunscrição da simulação.</p></div><button id="reset-scenarios">Restaurar premissas</button></div><div id="scenario-order" class="note warning" hidden></div><div class="scenario-grid">${S.scenarios.map((r,i)=>`<section class="scenario ${i===1?'mid':''}"><span class="tag">Hipótese editável</span><h3>${['Menor votação','Intermediária','Maior votação'][i]}</h3><p class="small">${['Participação inicial: 80% da referência','Participação inicial igual à referência','Participação inicial: 120% da referência'][i]}</p>${[['electorate','Eleitorado (pessoas)',1,1000000000],['turnout','Comparecimento (%)',.01,100],['valid','Válidos / comparecimento (%)',.01,100],['share','Candidato / votos válidos (%)',.01,100]].map(([k,l,step,max])=>`<div class="field"><label for="scenario-${i}-${k}">${l}</label><input id="scenario-${i}-${k}" data-scenario="${i}" data-key="${k}" type="number" min="0" max="${max}" step="${k==='electorate'?1:'any'}" value="${k==='electorate'?r[k]:r[k].toFixed(6)}"></div>`).join('')}<output id="scenario-output-${i}" aria-live="polite">${fmt(scenarioValue(r))}</output><span class="small">votos simulados, arredondados ao inteiro</span><p class="small" id="scenario-detail-${i}" style="margin-top:14px">${scenarioFormula(r)}</p></section>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><div><h2>Sensibilidade à participação do candidato</h2><p>Varia apenas a participação; mantém as outras premissas intermediárias.</p></div><button data-export="sensitivity-chart">Exportar gráfico</button></div><div class="panel-body" id="sensitivity">${sensitivity()}</div></section><div class="note">As taxas são aplicadas em sequência, não somadas. Comparecimento usa o eleitorado como base; válidos usam comparecimento; participação usa votos válidos nominais e de legenda. Altere qualquer premissa para explorar seu efeito.</div>`;}
function scenarioFormula(r){return `${fmt(r.electorate)} × ${fmt(r.turnout/100,4)} × ${fmt(r.valid/100,4)} × ${fmt(r.share/100,6)}`;}
function sensitivity(){const r=S.scenarios[1],vals=[.5,.75,1,1.25,1.5].map(v=>({share:Math.min(100,r.share*v),votes:scenarioValue({...r,share:Math.min(100,r.share*v)})})),max=Math.max(...vals.map(v=>v.votes),1);return `<svg id="sensitivity-chart" class="chart-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 245" role="img" aria-label="Simulação de sensibilidade à participação"><rect width="1000" height="245" fill="white"/><text x="18" y="22" fill="#566c7c" font-size="13" font-family="sans-serif">Simulação · eleitorado ${fmt(r.electorate)} · comparecimento ${pstr(r.turnout)} · válidos ${pstr(r.valid)}</text>${vals.map((v,i)=>{let h=v.votes/max*145,x=75+i*185;return `<rect x="${x}" y="${200-h}" width="90" height="${h}" fill="${i===2?'#007f82':'#a1cfcd'}" rx="3"/><text x="${x+45}" y="${190-h}" fill="#234056" font-size="15" font-family="sans-serif" text-anchor="middle">${fmt(v.votes)}</text><text x="${x+45}" y="222" fill="#637487" font-size="14" font-family="sans-serif" text-anchor="middle">${pstr(v.share)}</text>`}).join('')}</svg>`;}
function sourcesPage(){return `<div class="note teal">Fotografia dos dados consultados em <strong>7 de outubro de 2026</strong>. Os resultados não se atualizam automaticamente. Cada arquivo mantém seu próprio momento de geração.</div><div class="download-grid"><a href="achados.md" download>Principais achados</a><a href="base-tratada.json" download>Base tratada · JSON</a><a href="municipalities.csv" download>Municípios · CSV</a><a href="neighborhoods.csv" download>Bairros · CSV</a><a href="locations.csv" download>Locais · CSV</a><a href="secoes.json" download>Seções · JSON</a><a href="auditoria.json" download>Auditoria · JSON</a><a href="mudancas-cadastrais.json" download>Mudanças cadastrais</a><a href="metodologia.md" download>Metodologia completa</a></div><section class="panel"><div class="panel-head"><h2>Conferência dos totais</h2></div><div class="table-wrap"><table><thead><tr><th>Eleição</th><th class="number">Votos totais</th><th class="number">Δ municípios</th><th class="number">Δ bairros × capital</th><th class="number">Cobertura por votos</th><th class="number">Não classificados</th><th class="number">Δ válidos por seção</th></tr></thead><tbody>${D.elections.map(e=>`<tr><td>${e.year} · ${esc(e.office)}</td><td class="number">${fmt(e.totals.votes)}</td><td class="number">${fmt(e.audit.municipalityDifference)}</td><td class="number">${fmt(e.audit.neighborhoodDifference)}</td><td class="number">${pstr(e.audit.classifiedVoteCoverage)}</td><td class="number">${fmt(e.audit.unclassifiedVotes)}</td><td class="number">${fmt(e.audit.validVoteDifference)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">Δ = soma reconstruída menos total oficial. Cobertura = votos com bairro atribuído / votos do candidato em Florianópolis. Registros não classificados entram nas somas.</div></section><div class="two-col section-gap"><section class="panel sources"><div class="panel-head"><h2>Metodologia dos indicadores</h2></div><div class="panel-body"><details open><summary>Identidade e candidaturas</summary><p>Nome completo normalizado e data de nascimento (20/08/1984), confirmados no registro TSE. Foram pesquisados os arquivos de Santa Catarina de todos os pleitos bienais entre 2004 e 2026. Há cinco candidaturas correspondentes. Nenhuma correspondência foi encontrada em 2004, 2006, 2008, 2010, 2014, 2020 e 2024. Essa verificação não é uma certidão nacional de inexistência de candidaturas.</p></details><details open><summary>Percentuais e votos de legenda</summary><p>Participação local = votos válidos do candidato ÷ (votos nominais válidos + total de votos de legenda válidos) × 100. Conversões de votos nominais em legenda entram no denominador; votos brancos, nulos e anulados sub judice ficam fora. Contribuição territorial = votos do candidato no território ÷ total da candidatura na eleição.</p><p>Em 2012, o campo QT_TOTAL_VOTOS_VALIDOS da base histórica repete o total nominal: 220.003 na capital. O denominador usado é a soma dos componentes confirmados na base partidária: 220.003 + 16.537 = 236.540. Em 2026, o percentual publicado como pvapn pelo TSE usa votos concorrentes (vvc), que incluem sub judice; este painel usa válidos (vv).</p></details><details><summary>Seções, locais e bairros</summary><p>Chave: eleição + turno + município + zona + seção. Sempre usamos o cadastro da eleição correspondente, mesmo quando sua extração retrospectiva foi publicada em 2024. Não aplicamos a localização de 2026 a pleitos antigos. Em 2026, os boletins principais totalizados foram verificados por SHA-256; seções agregadas não são contadas duas vezes.</p><p>Quando o código de local do resultado difere do cadastro, procuramos o local original dentro do próprio arquivo daquele ano. Sem correspondência inequívoca, os votos ficam em “Não classificado”. Não classificamos endereços por suposição. A relação de locais, seções e divergências é exportável.</p></details><details><summary>Geografia e limites históricos</summary><p>Os mapas estaduais usam a malha municipal oficial do IBGE consultada nesta execução e a correspondência TSE–IBGE. A mesma malha é usada nos dois mapas de comparação, sem afirmar que reproduz limites passados. A granularidade por bairro é restrita a Florianópolis.</p><p>Sem uma malha de bairros validada para cada ano, não desenhamos polígonos de bairros. Mostramos os pontos do cadastro e a agregação por rótulo de bairro/localidade. Coordenadas ausentes ou fora da faixa geográfica de Florianópolis não são inventadas. Arquivos retrospectivos não garantem a precisão histórica das coordenadas.</p></details><details><summary>Concentração, evolução e cenários</summary><p>Top 5/10: soma dos primeiros territórios dividida pela soma dos votos no filtro ativo. Cobertura 50%/80%: menor quantidade de territórios, ordenados por votos, que atinge o limiar. Crescimento: (votos finais / iniciais − 1) × 100; base zero não gera percentual. Pontos percentuais: diferença entre participações locais.</p><p>Os cenários multiplicam eleitorado, comparecimento, taxa de válidos e participação. Valores iniciais de participação: 80%, 100% e 120% da referência, escolhas ilustrativas, não estimativas probabilísticas. Não há simulação de cadeiras.</p></details></div></section><section class="panel sources"><div class="panel-head"><h2>Lacunas e limites de interpretação</h2></div><div class="panel-body"><p><strong>2012 e 2018:</strong> os votos de Bruno fecham, mas a classificação individual dos votos válidos por seção não permite reproduzir com segurança o denominador municipal atualizado. Por isso os percentuais por bairro/local estão indisponíveis nesses anos. Divergências: −495 e −368 votos, respectivamente.</p><p><strong>2022 e 2026:</strong> locais sem correspondência histórica segura permanecem não classificados: 99 e 233 votos, respectivamente. Não há perda desses votos nos totais.</p><p><strong>Bairros não são domicílios:</strong> o agrupamento se refere ao local de votação. Mudanças de nome, endereço, seções e composição de locais são documentadas; continuidade dos limites não foi comprovada.</p><p><strong>Comparação de cargos:</strong> vereador é uma disputa municipal; deputado é estadual. Comparações usam territórios comuns e não inferem fidelidade, transferência de eleitores ou causalidade.</p><p><strong>Final não significa imutável:</strong> os resultados de 2026 estão com 100% das seções e totalização final no TSE. Decisões posteriores podem alterar resultados; a base guarda a fotografia consultada.</p><a href="mudancas-cadastrais.json" download>Consultar ${D.locationChanges.length} diferenças cadastrais identificadas</a><div class="section-gap"><h3>Momento das fontes</h3>${D.elections.map(e=>`<p>${e.year}: resultado/base ${esc(e.sourceUpdatedAt)}; cadastro ${esc(e.audit.registerGeneratedAt)}.</p>`).join('')}</div></div></section></div><section class="panel sources section-gap"><div class="panel-head"><h2>Fontes oficiais e rastreabilidade</h2><a href="fontes.json" download>Baixar manifesto</a></div><div class="panel-body source-list"><ul>${D.sources.map(s=>`<li><a target="_blank" rel="noopener" href="${esc(s.url)}">${esc(s.title||s.member||s.url.split('/').pop())}</a><br><small>Consulta: ${s.accessedAt} ${s.sha256?'· SHA-256 preservado no manifesto':''}</small></li>`).join('')}</ul><p>2026: cada município possui seu arquivo oficial; cada seção possui link do boletim e hash em <a href="secoes.json">secoes.json</a>. Os scripts de extração e validação acompanham o projeto local.</p></div></section>`;}
function title(){return S.route==='overview'?'Bruno Souza':S.route==='state'?'Mapa de Santa Catarina':names[S.route];}
function render(){const currentFocus=document.activeElement?.id;const e=election();$('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('state')}</div><div>Atlas eleitoral<span>SANTA CATARINA</span></div></div><div class="nav-label">EXPLORAR RESULTADOS</div><nav aria-label="Navegação principal">${Object.entries(names).map(([id,n])=>`<button data-route="${id}" class="${S.route===id?'active':''}" ${S.route===id?'aria-current="page"':''}>${icon(id)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>Bruno André de Souza</strong>5 candidaturas verificadas<br>2012 — 2026<br><br>Dados oficiais · TSE / IBGE<br>Consulta em 07 out 2026</div></aside><div class="workspace"><header class="topbar"><span class="crumb">Histórico eleitoral &nbsp; / &nbsp; ${names[S.route]}</span><span class="tag">Fonte oficial · 1º turno</span></header><main class="main"><div class="title-row"><div><div class="eyebrow">${S.route==='scenarios'?'SIMULAÇÃO EXPLORATÓRIA':'HISTÓRICO ELEITORAL · 2012–2026'}</div><h1>${title()}</h1><p>${S.route==='overview'?'Bruno André de Souza · Santa Catarina':S.route==='sources'?'Bases, critérios de agregação e conferência dos números.':S.route==='scenarios'?'Explore o efeito das premissas sobre a votação total.':S.route==='compare'?'Compare eleições no mesmo território, com escalas compatíveis.':`${e.year} · ${e.office} · ${e.party} · ${e.number}`}</p></div>${S.route==='overview'?`<span class="tag">${e.status}</span>`:''}</div>${S.route==='compare'?compare():S.route==='scenarios'?scenarios():S.route==='sources'?sourcesPage():overview()}<footer class="footer"><span>Atlas eleitoral · Bruno Souza · Dados descritivos, sem inferência sobre indivíduos.</span><span>TSE / TRE-SC / IBGE · consulta 07/10/2026</span></footer></main></div></div><div id="tooltip" class="tooltip" hidden></div>`;bind();if(currentFocus==='search'){const el=$('#search');if(el){el.focus();el.setSelectionRange(el.value.length,el.value.length);}}}
function selectYear(y){S.year=+y;S.office='all';S.selected=null;S.search='';S.scenarios=null;render();}
function download(content,name,type){saveBlob(new Blob([content],{type}),name);} function saveBlob(blob,name){const u=URL.createObjectURL(blob);const old=$('#export-ready');if(old){URL.revokeObjectURL(old.querySelector('a').href);old.remove();}const box=document.createElement('div');box.id='export-ready';box.className='export-ready';box.setAttribute('role','status');const text=document.createElement('span');text.textContent='Arquivo pronto: ';const a=document.createElement('a');a.href=u;a.download=name;a.textContent=name;box.append(text,a);const close=document.createElement('button');close.textContent='Fechar';close.onclick=()=>{URL.revokeObjectURL(u);box.remove();};box.append(close);document.body.append(box);a.click();}
function csv(rows,name){if(!rows.length){toast('Nenhum registro para exportar.');return;}const cols=Object.keys(rows[0]),quote=v=>'"'+String(v===null||v===undefined?'':v).replace(/"/g,'""')+'"';download('\uFEFF'+cols.map(quote).join(';')+'\r\n'+rows.map(r=>cols.map(k=>quote(typeof r[k]==='number'&&!Number.isInteger(r[k])?String(r[k]).replace('.',','):r[k])).join(';')).join('\r\n'),name,'text/csv;charset=utf-8');}
function exportRows(level){let e=election(),rows=level==='locations'?e.locations.filter(l=>e.neighborhoods.find(r=>r.id===S.selected)?.locationIds.includes(l.id)):rowsFor(e,level);csv(rows.map(r=>({ano:e.year,cargo:e.office,territorio:r.name,votos:r.votes,votos_validos:r.validVotes,percentual_validos:pct(r.votes,r.validVotes),percentual_total_candidato:pct(r.votes,e.totals.votes),bairro:r.neighborhood||'',zona:r.zone||'',local:r.code||'',endereco:r.address||'',fonte:'TSE',consulta:'2026-10-07'})),`bruno-souza-${e.year}-${level}-filtrado.csv`);}
async function exportImage(id){const original=document.getElementById(id);if(!original)return;const clone=original.cloneNode(true);const originalBox=original.viewBox.baseVal;const isMap=id.includes('map');const box={width:originalBox.width,height:originalBox.height+(isMap?105:35)};clone.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);clone.setAttribute('width',box.width);clone.setAttribute('height',box.height);const ns='http://www.w3.org/2000/svg';const white=document.createElementNS(ns,'rect');white.setAttribute('y',originalBox.height);white.setAttribute('width',box.width);white.setAttribute('height',isMap?105:35);white.setAttribute('fill','white');clone.appendChild(white);const caption=document.createElementNS(ns,'text');caption.setAttribute('x','20');caption.setAttribute('y',String(box.height-12));caption.setAttribute('font-size','12');caption.setAttribute('font-family','sans-serif');caption.setAttribute('fill','#4b6174');caption.textContent='Bruno Souza · TSE / IBGE · consulta 07/10/2026 · válidos incluem legenda';clone.appendChild(caption);if(isMap){let ts=thresholds();const labels=['Zero','> 0 – < '+ts[1],ts[1]+' – < '+ts[2],ts[2]+' – < '+ts[3],ts[3]+' – < '+ts[4],ts[4]+' ou mais'];colors.forEach((color,i)=>{let x=20+i*128;const sw=document.createElementNS(ns,'rect');for(const [k,v]of Object.entries({x,y:originalBox.height+12,width:18,height:12,fill:color,stroke:'#aab7c3'}))sw.setAttribute(k,v);clone.appendChild(sw);const tx=document.createElementNS(ns,'text');for(const [k,v]of Object.entries({x:x+23,y:originalBox.height+23,'font-size':11,'font-family':'sans-serif',fill:'#425a6e'}))tx.setAttribute(k,v);tx.textContent=labels[i]+(S.metric==='share'?'%':'');clone.appendChild(tx);});const tx=document.createElementNS(ns,'text');for(const [k,v]of Object.entries({x:20,y:originalBox.height+55,'font-size':11,'font-family':'sans-serif',fill:'#425a6e'}))tx.setAttribute(k,v);tx.textContent='Hachura: sem dado. Cinza: fora do filtro / não aplicável. Pontos: locais de votação, não residência.';clone.appendChild(tx);}const xml=new XMLSerializer().serializeToString(clone),u=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml'}));const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=box.width*2;canvas.height=box.height*2;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(b=>{saveBlob(b,`bruno-souza-${id}-${S.year}.png`);});URL.revokeObjectURL(u);};img.onerror=()=>{URL.revokeObjectURL(u);download(xml,id+'.svg','image/svg+xml');toast('Gráfico exportado em SVG.');};img.src=u;}
function toast(s){$('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.textContent=s;t.setAttribute('role','status');document.body.append(t);setTimeout(()=>t.remove(),3500);}
function showTooltip(event,el){const e=election(el.dataset.mapYear),level=el.dataset.mapLevel,r=e[level].find(a=>a.id===el.dataset.mapId);if(!r)return;const tip=$('#tooltip');tip.innerHTML=`<b>${esc(r.name)}</b><span>${e.year} · ${esc(e.office)}</span>${fmt(r.votes)} votos<span>${pstr(pct(r.votes,r.validVotes))} dos ${fmt(r.validVotes)} válidos locais</span><span>${pstr(pct(r.votes,e.totals.votes))} do total do candidato</span>${r.neighborhood?`<span>${esc(r.neighborhood)}</span>`:''}`;tip.hidden=false;const rect=el.getBoundingClientRect(),x=event.clientX??rect.left,y=event.clientY??rect.top;tip.style.left=Math.max(8,Math.min(innerWidth-300,x+14))+'px';tip.style.top=Math.max(8,Math.min(innerHeight-170,y+14))+'px';}
function bind(){const on=(sel,event,fn)=>{const el=$(sel);if(el)el.addEventListener(event,fn);};
 $$('[data-route]').forEach(b=>b.onclick=()=>{S.route=b.dataset.route;S.selected=null;S.search='';S.scenarios=null;if(S.route==='state')S.territory='SC';render();window.scrollTo(0,0);});
 on('#year','change',e=>{S.year=+e.target.value;S.selected=null;S.scenarios=null;render();});
 on('#office','change',e=>{S.office=e.target.value;if(S.office!=='all'&&election().officeCode!==+S.office)S.year=[...D.elections].reverse().find(a=>a.officeCode===+S.office).year;S.selected=null;S.scenarios=null;render();});
 on('#territory','change',e=>{S.territory=e.target.value;S.selected=null;S.scenarios=null;render();});
 on('#search','input',e=>{S.search=e.target.value;S.selected=null;render();});
 on('#clear','click',()=>{Object.assign(S,{year:2026,office:'all',territory:'SC',search:'',metric:'votes',sort:'votes',selected:null,scenarios:null});render();});
 $$('[data-year]').forEach(b=>b.onclick=()=>selectYear(b.dataset.year));
 $$('[data-metric]').forEach(b=>b.onclick=()=>{S.metric=b.dataset.metric;render();});
 $$('[data-select]').forEach(b=>b.onclick=()=>{S.selected=b.dataset.select;render();if(b.dataset.level==='neighborhoods')$('#location-detail')?.scrollIntoView({behavior:'smooth',block:'start'});});
 on('#ranking-sort','change',e=>{S.sort=e.target.value;render();});$$('[data-sort]').forEach(b=>b.onclick=()=>{S.sort=b.dataset.sort;render();});
 on('#drill','click',()=>{S.route='neighborhoods';S.search='';S.selected=null;render();});on('#deselect','click',()=>{S.selected=null;render();});
 $$('[data-map-id]').forEach(el=>{el.addEventListener('mousemove',e=>showTooltip(e,el));el.addEventListener('focus',e=>showTooltip(e,el));el.addEventListener('mouseleave',()=>$('#tooltip').hidden=true);el.addEventListener('blur',()=>$('#tooltip').hidden=true);const activate=()=>{if(S.route==='compare'){showTooltip({},el);return;}S.selected=el.dataset.mapId;render();};el.addEventListener('click',activate);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}});});
 $$('[data-export]').forEach(b=>b.onclick=()=>exportImage(b.dataset.export));on('#export-csv','click',()=>exportRows(S.route==='neighborhoods'?'neighborhoods':'municipalities'));on('#export-locations','click',()=>exportRows('locations'));
 on('#compare-a','change',e=>{S.compareA=+e.target.value;render();});on('#compare-b','change',e=>{S.compareB=+e.target.value;render();});on('#compare-level','change',e=>{S.compareLevel=e.target.value;S.search='';render();});on('#export-comparison','click',()=>csv(comparisonRows().map(r=>({ano_inicial:S.compareA,ano_final:S.compareB,territorio:r.name,votos_iniciais:r.a?.votes,votos_finais:r.b?.votes,variacao_votos:r.delta,variacao_percentual:r.growth,variacao_pontos_percentuais:r.pp,base_inicial_pequena:r.a&&r.a.votes<100?'sim':'não'})),`comparacao-${S.compareA}-${S.compareB}.csv`));
 on('#reset-scenarios','click',()=>{initScenarios(true);render();});$$('[data-scenario]').forEach(el=>el.oninput=()=>{const i=+el.dataset.scenario,k=el.dataset.key,v=Number(el.value);if(el.value===''||!Number.isFinite(v)||v<0||v>Number(el.max)){el.setCustomValidity('Informe um valor dentro do intervalo indicado.');return;}el.setCustomValidity('');S.scenarios[i][k]=v;$('#scenario-output-'+i).textContent=fmt(scenarioValue(S.scenarios[i]));$('#scenario-detail-'+i).textContent=scenarioFormula(S.scenarios[i]);$('#sensitivity').innerHTML=sensitivity();const ordered=S.scenarios.map(scenarioValue);$('#scenario-order').hidden=ordered[0]<=ordered[1]&&ordered[1]<=ordered[2];$('#scenario-order').textContent='As premissas editadas inverteram a ordem dos cenários. Os rótulos descrevem as hipóteses iniciais; confira os totais simulados.';});
}
try{render();}catch(error){console.error(error);$('#app').innerHTML='<main class="main"><h1>Não foi possível carregar o dashboard</h1><p>Recarregue a página. A base pode ser consultada em <a href="base-tratada.json">JSON</a>.</p></main>';}
